# Runtime function: BUILD_HYBRID_ETA_SERVICE_RESPONSE_V1
def BUILD_HYBRID_ETA_SERVICE_RESPONSE_V1(
    normalized_journey_df,
):
    """
    Build the final application-facing response.

    No actual or provider-estimated arrival for an upcoming
    station is used as an input feature.
    """

    predictions_df = predict_hybrid_station_etas(
        normalized_journey_df
    )

    if predictions_df.empty:
        return {
            "success": True,
            "journey": None,
            "predictions": [],
            "message": (
                "No upcoming stations are available "
                "for this journey."
            ),
        }

    route_df = (
        normalized_journey_df
        .copy()
        .reset_index(drop=True)
    )

    observed_mask = (
        route_df["arrival_is_observed"]
        .fillna(False)
        .astype(bool)
    )

    observed_df = route_df.loc[
        observed_mask
    ].copy()

    if observed_df.empty:
        raise ValueError(
            "At least one verified observed arrival "
            "is required for dynamic ETA prediction."
        )

    sort_column = (
        "halt_order"
        if "halt_order" in observed_df.columns
        else "station_sequence"
    )

    observed_df = observed_df.sort_values(
        sort_column
    )

    current_row = observed_df.iloc[-1]

    first_prediction = predictions_df.iloc[0]

    journey_id = (
        str(first_prediction.get("journey_id"))
        if pd.notna(
            first_prediction.get("journey_id")
        )
        else None
    )

    train_number = (
        str(first_prediction.get("train_number"))
        if pd.notna(
            first_prediction.get("train_number")
        )
        else None
    )

    train_name = (
        str(first_prediction.get("train_name"))
        if pd.notna(
            first_prediction.get("train_name")
        )
        else None
    )

    current_station_code = str(
        current_row.get(
            "station_code",
            first_prediction.get(
                "current_station_code",
                "",
            ),
        )
    )

    current_station_name = str(
        current_row.get(
            "station_name",
            current_station_code,
        )
    )

    current_arrival = current_row.get(
        "actual_arrival"
    )

    current_delay = current_row.get(
        "arrival_delay_min"
    )

    if pd.isna(current_delay):
        current_delay = current_row.get(
            "calculated_arrival_delay_min"
        )

    station_predictions = []

    for _, prediction_row in (
        predictions_df
        .sort_values("stations_ahead")
        .iterrows()
    ):
        engine = str(
            prediction_row["prediction_engine"]
        )

        fallback_used = bool(
            prediction_row["fallback_used"]
        )

        interval_radius = safe_json_number(
            prediction_row[
                "prediction_interval_radius_min"
            ],
            digits=1,
        )

        predicted_delay = safe_json_number(
            prediction_row[
                "predicted_arrival_delay_min"
            ],
            digits=1,
        )

        recent_baseline = safe_json_number(
            prediction_row[
                "recent_delay_baseline_min"
            ],
            digits=1,
        )

        model2_prediction = safe_json_number(
            prediction_row[
                "model2_prediction_min"
            ],
            digits=1,
        )

        model3_prediction = safe_json_number(
            prediction_row[
                "model3_prediction_min"
            ],
            digits=1,
        )

        if engine == "MODEL_2_NEXT_STATION":
            confidence = "HIGH"
            explanation = (
                "Immediate next-station ETA generated by "
                "Model 2, the cross-domain validated "
                "next-station specialist."
            )

        elif engine == "MODEL_3_NEXT_STATION_FALLBACK":
            confidence = "MEDIUM"
            explanation = (
                "Model 2 was unavailable, so the guarded "
                "multi-horizon Model 3 prediction was used."
            )

        else:
            confidence = "MEDIUM"
            explanation = (
                "Multi-horizon ETA generated from the "
                "recent observed-delay baseline plus the "
                "guarded Model 3 correction."
            )

        station_response = {
            "station": {
                "code": str(
                    prediction_row[
                        "target_station_code"
                    ]
                ),
                "name": str(
                    prediction_row[
                        "target_station_name"
                    ]
                ),
                "stations_ahead": int(
                    prediction_row[
                        "stations_ahead"
                    ]
                ),
                "distance_km": safe_json_number(
                    prediction_row[
                        "distance_to_target_km"
                    ],
                    digits=1,
                ),
            },
            "schedule": {
                "arrival": timestamp_to_indian_iso(
                    prediction_row[
                        "target_scheduled_arrival"
                    ]
                ),
            },
            "forecast": {
                "eta": timestamp_to_indian_iso(
                    prediction_row[
                        "predicted_eta"
                    ]
                ),
                "predicted_delay_min": (
                    predicted_delay
                ),
                "delay_status": str(
                    prediction_row[
                        "delay_status"
                    ]
                ),
                "lower_eta": timestamp_to_indian_iso(
                    prediction_row["eta_lower"]
                ),
                "upper_eta": timestamp_to_indian_iso(
                    prediction_row["eta_upper"]
                ),
                "interval_radius_min": (
                    interval_radius
                ),
                "confidence": confidence,
            },
            "model": {
                "prediction_engine": engine,
                "model2_prediction_min": (
                    model2_prediction
                ),
                "model3_prediction_min": (
                    model3_prediction
                ),
                "recent_delay_baseline_min": (
                    recent_baseline
                ),
                "fallback_used": fallback_used,
                "fallback_reason": (
                    prediction_row[
                        "fallback_reason"
                    ]
                    if fallback_used
                    else None
                ),
            },
            "explanation": explanation,
            "comparison_only": {
                "provider_eta": (
                    timestamp_to_indian_iso(
                        prediction_row.get(
                            "provider_estimated_arrival"
                        )
                    )
                ),
                "provider_delay_min": (
                    safe_json_number(
                        prediction_row.get(
                            "provider_predicted_delay_min"
                        ),
                        digits=1,
                    )
                ),
            },
        }

        station_predictions.append(
            station_response
        )

    response = {
        "success": True,
        "system": {
            "name": (
                "SIH 26028 Hybrid Dynamic ETA System"
            ),
            "architecture": {
                "next_station": (
                    "Model 2 next-station CatBoost"
                ),
                "later_stations": (
                    "Guarded residual Model 3"
                ),
                "provider_forecast_usage": (
                    "comparison_only"
                ),
            },
            "leakage_safe": True,
        },
        "journey": {
            "journey_id": journey_id,
            "train_number": train_number,
            "train_name": train_name,
            "current_station_code": (
                current_station_code
            ),
            "current_station_name": (
                current_station_name
            ),
            "current_observed_arrival": (
                timestamp_to_indian_iso(
                    current_arrival
                )
            ),
            "current_delay_min": (
                safe_json_number(
                    current_delay,
                    digits=1,
                )
            ),
            "observed_stations": int(
                observed_mask.sum()
            ),
            "upcoming_stations": int(
                len(predictions_df)
            ),
        },
        "predictions": station_predictions,
    }

    return response


# Runtime function: MODEL2_PREDICTOR_BEFORE_EARLY_POLICY
def MODEL2_PREDICTOR_BEFORE_EARLY_POLICY(
    normalized_journey_df,
):
    features_df, current, next_station = (
        build_model2_live_features(
            normalized_journey_df
        )
    )

    raw_prediction = float(
        deployed_model2.predict(
            features_df
        )[0]
    )

    # Model 2 was trained on non-negative delay labels.
    model2_prediction = max(
        0.0,
        raw_prediction,
    )

    current_delay = float(
        current["arrival_delay_min"]
    )

    model2_applicable = (
        current_delay >= 0
    )

    return {
        "train_number":
            str(current["train_number"]),
        "current_station_code":
            str(current["station_code"]),
        "next_station_code":
            str(next_station["station_code"]),
        "current_delay_min":
            current_delay,
        "model2_raw_prediction_min":
            raw_prediction,
        "model2_prediction_min":
            model2_prediction,
        "model2_applicable":
            model2_applicable,
        "not_applicable_reason":
            (
                None
                if model2_applicable
                else
                "Model 2 training labels did not "
                "contain early/negative delays."
            ),
        "features": features_df,
    }


