# Runtime function: build_live_inference_rows
def build_live_inference_rows(
    normalized_journey_df,
):
    """
    Build one inference row for every station ahead of the
    latest verified station.

    Only observed past events are used for current-state
    features. Provider forecasts are excluded from features.
    """

    journey_df = (
        normalized_journey_df
        .copy()
        .sort_values(
            [
                "halt_order",
                "station_sequence",
            ]
        )
        .reset_index(drop=True)
    )

    observed_df = journey_df[
        journey_df["arrival_is_observed"]
        & journey_df["actual_arrival"].notna()
        & journey_df["arrival_delay_min"].notna()
    ].copy()

    if observed_df.empty:
        raise ValueError(
            "No verified station arrival is available. "
            "Model 3 requires at least one observed station."
        )

    current = (
        observed_df
        .sort_values(
            [
                "halt_order",
                "station_sequence",
            ]
        )
        .iloc[-1]
    )

    upcoming_df = journey_df[
        (
            journey_df["halt_order"]
            > current["halt_order"]
        )
        & (
            ~journey_df[
                "arrival_is_observed"
            ]
        )
    ].copy()

    if upcoming_df.empty:
        return (
            pd.DataFrame(),
            current,
        )

    observed_delays = (
        observed_df[
            "arrival_delay_min"
        ]
        .dropna()
        .astype(float)
        .tolist()
    )

    current_delay = float(
        current["arrival_delay_min"]
    )

    previous_delay_1 = (
        observed_delays[-2]
        if len(observed_delays) >= 2
        else np.nan
    )

    previous_delay_2 = (
        observed_delays[-3]
        if len(observed_delays) >= 3
        else np.nan
    )

    previous_delay_3 = (
        observed_delays[-4]
        if len(observed_delays) >= 4
        else np.nan
    )

    rolling_delays = observed_delays[-3:]

    rolling_mean = float(
        np.mean(rolling_delays)
    )

    rolling_std = (
        float(
            np.std(
                rolling_delays,
                ddof=1,
            )
        )
        if len(rolling_delays) >= 2
        else np.nan
    )

    current_delay_change = (
        current_delay - previous_delay_1
        if pd.notna(previous_delay_1)
        else np.nan
    )

    inference_rows = []

    for _, target in upcoming_df.iterrows():
        stations_ahead = int(
            target["halt_order"]
            - current["halt_order"]
        )

        distance_to_target = (
            target[
                "distance_from_source_km"
            ]
            - current[
                "distance_from_source_km"
            ]
        )

        scheduled_minutes_to_target = (
            target["scheduled_arrival"]
            - current["scheduled_arrival"]
        ).total_seconds() / 60

        inference_rows.append({
            "journey_id":
                current["journey_id"],
            "train_number":
                current["train_number"],
            "train_name":
                current["train_name"],

            "current_station_code":
                current["station_code"],
            "target_station_code":
                target["station_code"],
            "target_station_name":
                target["station_name"],

            "current_halt_order":
                current["halt_order"],
            "current_station_sequence":
                current["station_sequence"],
            "current_distance_from_source_km":
                current[
                    "distance_from_source_km"
                ],
            "current_route_progress":
                current["route_progress"],

            "target_halt_order":
                target["halt_order"],
            "target_station_sequence":
                target["station_sequence"],
            "target_distance_from_source_km":
                target[
                    "distance_from_source_km"
                ],

            "current_arrival_delay_min":
                current_delay,
            "current_departure_delay_min":
                current[
                    "departure_delay_min"
                ],

            "previous_arrival_delay_1":
                previous_delay_1,
            "previous_arrival_delay_2":
                previous_delay_2,
            "previous_arrival_delay_3":
                previous_delay_3,

            "current_delay_change":
                current_delay_change,
            "delay_rolling_mean_3":
                rolling_mean,
            "delay_rolling_std_3":
                rolling_std,
            "observed_stations_so_far":
                len(observed_delays),

            "stations_ahead":
                stations_ahead,
            "distance_to_target_km":
                distance_to_target,
            "scheduled_minutes_to_target":
                scheduled_minutes_to_target,

            "journey_day_of_week":
                current[
                    "scheduled_arrival"
                ].dayofweek,
            "journey_month":
                current[
                    "scheduled_arrival"
                ].month,
            "current_hour":
                current[
                    "scheduled_arrival"
                ].hour,
            "target_hour":
                target[
                    "scheduled_arrival"
                ].hour,

            "target_scheduled_arrival":
                target["scheduled_arrival"],

            # Kept only for comparison—not a model input.
            "provider_estimated_arrival":
                target[
                    "provider_estimated_arrival"
                ],
        })

    inference_df = pd.DataFrame(
        inference_rows
    )

    return inference_df, current


# Runtime function: build_model2_live_features
def build_model2_live_features(
    normalized_journey_df,
):
    """
    Build Model 2 features for the immediate next halt.

    Returns:
        feature DataFrame,
        current station row,
        next station row.
    """

    journey_df = (
        normalized_journey_df
        .copy()
        .sort_values("halt_order")
        .reset_index(drop=True)
    )

    observed_df = journey_df[
        journey_df["arrival_is_observed"]
        & journey_df["actual_arrival"].notna()
        & journey_df["arrival_delay_min"].notna()
    ].copy()

    if observed_df.empty:
        raise ValueError(
            "Model 2 needs at least one "
            "observed station."
        )

    current = observed_df.iloc[-1]

    future_df = journey_df[
        (
            journey_df["halt_order"]
            > current["halt_order"]
        )
        & (
            ~journey_df[
                "arrival_is_observed"
            ]
        )
    ].copy()

    if future_df.empty:
        raise ValueError(
            "No upcoming station remains."
        )

    next_station = future_df.iloc[0]

    observed_delays = (
        observed_df[
            "arrival_delay_min"
        ]
        .astype(float)
        .tolist()
    )

    current_delay = float(
        observed_delays[-1]
    )

    prev_delay_1 = (
        observed_delays[-2]
        if len(observed_delays) >= 2
        else np.nan
    )

    prev_delay_2 = (
        observed_delays[-3]
        if len(observed_delays) >= 3
        else np.nan
    )

    delay_change_prev = (
        current_delay - prev_delay_1
        if pd.notna(prev_delay_1)
        else np.nan
    )

    delay_trend_2 = (
        current_delay - prev_delay_2
        if pd.notna(prev_delay_2)
        else np.nan
    )

    segment_distance = (
        next_station[
            "distance_from_source_km"
        ]
        - current[
            "distance_from_source_km"
        ]
    )

    current_scheduled_departure = (
        current["scheduled_departure"]
    )

    if pd.isna(
        current_scheduled_departure
    ):
        current_scheduled_departure = (
            current["scheduled_arrival"]
        )

    scheduled_segment_minutes = (
        next_station[
            "scheduled_arrival"
        ]
        - current_scheduled_departure
    ).total_seconds() / 60

    if scheduled_segment_minutes <= 0:
        raise ValueError(
            "Invalid scheduled segment duration."
        )

    scheduled_segment_speed = (
        segment_distance
        / (
            scheduled_segment_minutes / 60
        )
    )

    total_halts = float(
        journey_df["halt_order"].max()
    )

    route_progress_safe = (
        float(current["halt_order"])
        / total_halts
    )

    scheduled_departure = pd.to_datetime(
        current_scheduled_departure,
        utc=True,
    )

    feature_row = {
        "current_delay":
            current_delay,

        "prev_delay_1":
            prev_delay_1,
        "prev_delay_2":
            prev_delay_2,
        "delay_change_prev":
            delay_change_prev,
        "delay_trend_2":
            delay_trend_2,

        "segment_distance":
            segment_distance,
        "scheduled_segment_minutes":
            scheduled_segment_minutes,
        "scheduled_segment_speed":
            scheduled_segment_speed,

        # Halt order is used because the training model
        # rebuilt a continuous station sequence.
        "station_sequence":
            int(current["halt_order"]),

        "route_progress_safe":
            route_progress_safe,

        "departure_hour":
            int(scheduled_departure.hour),
        "day_of_week":
            int(scheduled_departure.dayofweek),
        "is_weekend":
            int(
                scheduled_departure.dayofweek
                >= 5
            ),

        "train":
            str(current["train_number"]),
        "station":
            str(current["station_code"]),
        "next_station":
            str(
                next_station[
                    "station_code"
                ]
            ),
    }

    features_df = pd.DataFrame(
        [feature_row]
    )

    for column in (
        MODEL2_CATEGORICAL_FEATURES
    ):
        features_df[column] = (
            features_df[column]
            .astype(str)
        )

    features_df = features_df[
        MODEL2_FEATURES
    ]

    return (
        features_df,
        current,
        next_station,
    )


