# Runtime function: run_live_train_forecast
def run_live_train_forecast(
    train_number,
    journey_date,
):
    train_number = str(
        train_number or ""
    ).strip()

    journey_date = str(
        journey_date or ""
    ).strip()

    if not train_number:
        return service_response_to_dashboard(
            {
                "success": False,
                "message": (
                    "Enter a train number."
                ),
            }
        )

    if not train_number.isdigit():
        return service_response_to_dashboard(
            {
                "success": False,
                "message": (
                    "Train number must contain "
                    "digits only."
                ),
            }
        )

    try:
        response = forecast_train_etas(
            train_number=train_number,
            journey_date=(
                journey_date
                if journey_date
                else None
            ),
            save_result=True,
        )

        # forecast_train_etas already uses the active hybrid
        # builder for a running journey.
        if isinstance(response, dict):
            response.setdefault(
                "operational_stage",
                "RUNNING",
            )

        return service_response_to_dashboard(
            response
        )

    except Exception as error:
        return service_response_to_dashboard(
            {
                "success": False,
                "message": (
                    f"{type(error).__name__}: {error}"
                ),
            }
        )


# Runtime function: safe_datetime
def safe_datetime(series):
    """
    Convert timestamp values to timezone-aware UTC timestamps.
    Invalid or missing values become NaT.
    """
    return pd.to_datetime(
        series,
        errors="coerce",
        utc=True,
    )


# Runtime function: safe_filename
def safe_filename(value):
    return re.sub(
        r"[^A-Za-z0-9_.-]+",
        "_",
        str(value),
    )


# Runtime function: safe_json_number
def safe_json_number(value, digits=2):
    """
    Convert NumPy/pandas numeric values into JSON-safe numbers.
    """

    if value is None or pd.isna(value):
        return None

    numeric_value = float(value)

    if not math.isfinite(numeric_value):
        return None

    return round(numeric_value, digits)


# Runtime function: safe_public_number
def safe_public_number(
    value,
    digits=1,
):
    if value is None or pd.isna(value):
        return None

    try:
        numeric_value = float(value)
    except (TypeError, ValueError):
        return None

    if not math.isfinite(numeric_value):
        return None

    return round(
        numeric_value,
        digits,
    )


# Runtime function: save_raw_response
def save_raw_response(api_result):
    data = api_result.get("data", {})

    train_number = safe_filename(
        data.get("trainNumber", "unknown")
    )
    start_date = safe_filename(
        data.get("startDate", "unknown")
    )

    timestamp = datetime.now(timezone.utc).strftime(
        "%Y%m%dT%H%M%SZ"
    )

    journey_folder = (
        RAW_DIR / f"{train_number}_{start_date}"
    )
    journey_folder.mkdir(parents=True, exist_ok=True)

    filepath = journey_folder / f"{timestamp}.json"

    with open(filepath, "w", encoding="utf-8") as file:
        json.dump(
            api_result,
            file,
            indent=2,
            ensure_ascii=False,
        )

    return filepath


# Runtime function: service_response_to_dashboard
def service_response_to_dashboard(
    response,
):
    if not isinstance(response, dict):
        return (
            "### Forecast failed\nInvalid response.",
            pd.DataFrame(),
            {"error": "Invalid response"},
        )

    if not response.get("success", False):
        return (
            "### Forecast failed\n"
            + str(
                response.get(
                    "message",
                    response.get(
                        "detail",
                        "Unknown error",
                    ),
                )
            ),
            pd.DataFrame(),
            convert_to_json_safe(response),
        )

    operational_stage = response.get(
        "operational_stage",
        "RUNNING",
    )

    # --------------------------------------------------------
    # Pre-departure Model 1 response
    # --------------------------------------------------------

    if operational_stage == "PRE_DEPARTURE":
        model1_output = response[
            "predeparture_forecast"
        ]

        forecast = model1_output["forecast"]

        summary_markdown = f"""
### Pre-departure destination-delay forecast

- **Selected model:** Model 1
- **Predicted destination delay:** {forecast['predicted_destination_delay_min']} minutes
- **Risk level:** {forecast['risk_level']}
- **Uncertainty range:** {forecast['lower_delay_min']} to {forecast['upper_delay_min']} minutes
- **Confidence:** {forecast['confidence']}

Model 1 is only a pre-departure destination-delay prior. It does not generate station-level ETAs.
"""

        return (
            summary_markdown,
            pd.DataFrame(),
            convert_to_json_safe(response),
        )

    # --------------------------------------------------------
    # Completed response
    # --------------------------------------------------------

    if operational_stage == "COMPLETED":
        journey = response.get(
            "journey",
            {},
        )

        summary_markdown = f"""
### Journey completed

- **Train:** {journey.get('train_number')}
- **Journey ID:** {journey.get('journey_id')}
- **Observed stations:** {journey.get('observed_stations')}
- **Upcoming stations:** 0

No additional ETA forecast is required.
"""

        return (
            summary_markdown,
            pd.DataFrame(),
            convert_to_json_safe(response),
        )

    # --------------------------------------------------------
    # Running Model 2 + Model 3 response
    # --------------------------------------------------------

    journey = response.get(
        "journey",
        {},
    )

    predictions = response.get(
        "predictions",
        [],
    )

    summary_markdown = f"""
### Live dynamic ETA forecast

- **Train:** {journey.get('train_number')} — {journey.get('train_name')}
- **Current station:** {journey.get('current_station_code')} — {journey.get('current_station_name')}
- **Current observed delay:** {journey.get('current_delay_min')} minutes
- **Observed stations:** {journey.get('observed_stations')}
- **Upcoming stations:** {len(predictions)}
- **Next station engine:** Model 2
- **Later station engine:** Model 3
"""

    table_rows = []

    for prediction in predictions:
        station = prediction["station"]
        forecast = prediction["forecast"]
        model = prediction["model"]
        comparison = prediction.get(
            "comparison_only",
            {},
        )

        table_rows.append(
            {
                "Station code": station["code"],
                "Station name": station["name"],
                "Stations ahead": station[
                    "stations_ahead"
                ],
                "Distance km": station[
                    "distance_km"
                ],
                "Predicted delay min": forecast[
                    "predicted_delay_min"
                ],
                "Status": forecast[
                    "delay_status"
                ],
                "Predicted ETA": forecast["eta"],
                "Lower ETA": forecast["lower_eta"],
                "Upper ETA": forecast["upper_eta"],
                "Confidence": forecast[
                    "confidence"
                ],
                "Prediction engine": model[
                    "prediction_engine"
                ],
                "Provider ETA (comparison)": (
                    comparison.get(
                        "provider_eta"
                    )
                ),
            }
        )

    prediction_table = pd.DataFrame(
        table_rows
    )

    return (
        summary_markdown,
        prediction_table,
        convert_to_json_safe(response),
    )


# Runtime function: timestamp_to_indian_iso
def timestamp_to_indian_iso(value):
    """
    Convert a timestamp into an ISO-8601 timestamp in IST.
    """

    timestamp = pd.to_datetime(
        value,
        utc=True,
        errors="coerce",
    )

    if pd.isna(timestamp):
        return None

    return timestamp.tz_convert(
        INDIAN_TIMEZONE
    ).isoformat()


# Runtime function: upsert_station_events
def upsert_station_events(new_df):
    incoming = new_df.copy()

    arrival_observed = (
        incoming["arrival_is_observed"]
        .fillna(False)
        .astype(bool)
    )

    departure_observed = (
        incoming["departure_is_observed"]
        .fillna(False)
        .astype(bool)
    )

    incoming = incoming[
        arrival_observed | departure_observed
    ].copy()

    for column in EVENT_V2_COLUMNS:
        if column not in incoming.columns:
            incoming[column] = pd.NA

    incoming = incoming[EVENT_V2_COLUMNS]
    incoming = canonicalize_timestamp_columns(incoming)

    if STATION_EVENT_FILE.exists():
        existing = pd.read_csv(
            STATION_EVENT_FILE,
            dtype={
                "journey_id": "string",
                "train_number": "string",
                "station_code": "string",
            },
            low_memory=False,
        )

        for column in EVENT_V2_COLUMNS:
            if column not in existing.columns:
                existing[column] = pd.NA

        existing = existing[EVENT_V2_COLUMNS]
        existing = canonicalize_timestamp_columns(existing)

        combined = pd.concat(
            [existing, incoming],
            ignore_index=True,
        )
    else:
        combined = incoming

    combined["_update_sort"] = pd.to_datetime(
        combined["source_last_updated_at"],
        errors="coerce",
        utc=True,
    )

    combined = (
        combined
        .sort_values("_update_sort")
        .drop_duplicates(
            subset=[
                "journey_id",
                "station_sequence",
                "station_code",
            ],
            keep="last",
        )
        .drop(columns=["_update_sort"])
        .reset_index(drop=True)
    )

    combined.to_csv(
        STATION_EVENT_FILE,
        index=False,
    )

    return len(incoming), len(combined)


# Runtime function: write_api_log
def write_api_log(
    endpoint,
    http_status,
    success,
    response_time_seconds,
    train_number=None,
    journey_date=None,
    error_code=None,
    error_message=None,
):
    row = {
        "requested_at_utc":
            datetime.now(timezone.utc).isoformat(),
        "endpoint": endpoint,
        "http_status": http_status,
        "success": success,
        "train_number": train_number,
        "journey_date": journey_date,
        "response_time_seconds":
            round(response_time_seconds, 3),
        "error_code": error_code,
        "error_message": error_message,
    }

    with open(
        API_LOG_FILE,
        "a",
        newline="",
        encoding="utf-8",
    ) as file:
        writer = csv.DictWriter(
            file,
            fieldnames=API_LOG_COLUMNS,
        )
        writer.writerow(row)
